// Runs transcripts of a real recording through the question editor. The transcripts stay outside the repo:
//   node node_modules/tsx/dist/cli.mjs research/voice-duplex/experiments/expE/real_call.ts <folder with transcripts.json and reference.json>
// Prints, per clip and per recogniser, whether code would answer or hand off, and the words it could not explain.
import { readFileSync } from "node:fs";
import { editCard } from "@/lib/ai/voice-query-editor";
import type { Card } from "@/lib/ai/voice-query";

const folder = process.argv[2];
const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const list = (names: string, offset: number) => names.split(", ").map((name, index) => ({ id: id(offset + index), name }));
const entities = {
  categories: list("Groceries, Shopping, Subscriptions, Transport, Restaurants, Coffee, Rent, Salary", 100),
  merchants: list("Rewe, Lidl, Netto, Amazon, Netflix, Spotify, Uber, Shell, Vapiano, Starbucks", 200),
  accounts: list("N26, Cash wallet", 300),
};
const whistle = JSON.parse(readFileSync(`${folder}/transcripts.json`, "utf8")) as { clip: string; names: string; audio_s: number; names_ms: number }[];
const reference = JSON.parse(readFileSync(`${folder}/reference.json`, "utf8")) as Record<string, string>;
const words = (text: string) => text.toLowerCase().replace(/[^a-z0-9 ]+/g, " ").split(/\s+/).filter(Boolean);
function distance(a: string[], b: string[]) {
  const row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) { let previous = row[0]; row[0] = i;
    for (let j = 1; j <= b.length; j++) { const keep = row[j]; row[j] = Math.min(row[j] + 1, row[j - 1] + 1, previous + (a[i - 1] === b[j - 1] ? 0 : 1)); previous = keep; } }
  return row[b.length];
}
const show = (card: Card) => `${card.metric} ${[...card.categories, ...card.merchants, ...card.accounts].map(ref => ref.name).join("+") || "all"} ${card.period.say}${card.comparison ? ` vs ${card.comparison.say}` : ""}${card.groupBy ? ` by ${card.groupBy}` : ""}`;
let errors = 0, total = 0;
const latency: number[] = [];
const cards: Record<string, Card | null> = { whistle: null, reference: null };
for (const row of whistle) {
  const texts = { whistle: row.names, reference: reference[row.clip] };
  const refWords = words(texts.reference);
  if (refWords.length > 2) { errors += distance(words(texts.whistle), refWords); total += refWords.length; latency.push(row.names_ms / 1000 / row.audio_s); }
  const outcome = (["whistle", "reference"] as const).map(source => {
    const result = editCard(cards[source], texts[source], entities, new Date().toISOString().slice(0, 10));
    const fast = result.touched && !result.leftover.length;
    cards[source] = fast ? result.card : null;
    return `${source.padEnd(9)} ${fast ? `CODE  ${show(result.card)}` : `MODEL (${result.leftover.slice(0, 8).join(" ")})`}`;
  });
  console.log(`${row.clip} ${row.audio_s}s\n  ${outcome.join("\n  ")}`);
}
console.log(`\nWhistle vs reference: ${Math.round(100 * errors / total)}% of words differ (${errors}/${total}); Whistle takes ${(100 * latency.reduce((a, b) => a + b, 0) / latency.length).toFixed(0)}% of the clip's length on average`);
// Runs transcripts of a real recording through the "add" draft editor. Transcripts stay outside the repo:
//   node node_modules/tsx/dist/cli.mjs research/voice-duplex/experiments/expE/real_adds.ts <folder with transcripts.json and reference.json>
import { readFileSync } from "node:fs";
import { editDraft, type Draft } from "@/lib/ai/voice-draft";

const folder = process.argv[2];
const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const list = (names: string, offset: number) => names.split(", ").map((name, index) => ({ id: id(offset + index), name }));
const entities = {
  categories: list("Groceries, Shopping, Subscriptions, Transport, Restaurants, Coffee, Rent, Salary", 100),
  merchants: list("Rewe, Lidl, Netto, Amazon, Netflix, Spotify, Uber, Shell, Vapiano, Starbucks", 200),
  accounts: list("N26, Cash wallet", 300),
};
const whistle = JSON.parse(readFileSync(`${folder}/transcripts.json`, "utf8")) as { clip: string; names: string }[];
const reference = JSON.parse(readFileSync(`${folder}/reference.json`, "utf8")) as Record<string, string>;
const drafts: Record<string, Draft | null> = { whistle: null, reference: null };
const counts = { whistle: 0, reference: 0 };
for (const row of whistle) {
  const lines = (["whistle", "reference"] as const).map(source => {
    const result = editDraft(drafts[source], source === "whistle" ? row.names : reference[row.clip], entities, new Date().toISOString().slice(0, 10), "EUR");
    drafts[source] = result.ready ? result.draft : null;
    if (result.ready) counts[source]++;
    const { draft } = result;
    return `${source.padEnd(9)} ${result.ready ? `CARD  ${draft.direction} ${draft.amount} ${draft.currency} · ${draft.merchant ?? "-"} · ${draft.category ?? "-"} · ${draft.account ?? "-"}` : result.adds ? `MODEL (add, unclear: ${result.unclear.join(", ")})` : "MODEL (not an add)"}`;
  });
  console.log(`${row.clip}\n  ${lines.join("\n  ")}`);
}
console.log(`\ncards from code: ${counts.reference} with the reference transcript, ${counts.whistle} with Whistle`);

"""Small Whisper-family recognisers on the same clips: word differences vs the large reference, and speed."""
import glob, json, os, re, sys, time
from faster_whisper import WhisperModel

folder = sys.argv[1]
ref = json.load(open(f"{folder}/reference.json", encoding="utf-8"))
whistle = {r["clip"]: r for r in json.load(open(f"{folder}/transcripts.json", encoding="utf-8"))}
words = lambda t: re.sub(r"[^a-z0-9 ]+", " ", t.lower()).split()
def dist(a, b):
    row = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        prev, row[0] = row[0], i
        for j in range(1, len(b) + 1):
            keep = row[j]; row[j] = min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] != b[j - 1])); prev = keep
    return row[-1]
KEY = ["rewe", "lidl", "netto", "amazon", "netflix", "munich", "scalable", "euros", "add", "spend", "earn", "salary", "groceries", "month", "year", "wallet"]
def score(hyp):
    e = t = k = kt = 0
    for clip, r in ref.items():
        rw = words(r)
        if len(rw) <= 2: continue
        hw = words(hyp[clip]); e += dist(hw, rw); t += len(rw)
        for w in KEY:
            n = rw.count(w); kt += n; k += min(n, hw.count(w))
    return round(100 * e / t), round(100 * k / kt)
prompt = "Moneo, Rewe, Lidl, Netto, Amazon, Netflix, Spotify, Scalable, N26, euros, groceries, salary."
out = {"whistle (17 MB)": {"diff%": score({c: r["names"] for c, r in whistle.items()})[0], "key words kept%": score({c: r["names"] for c, r in whistle.items()})[1],
       "time vs audio%": round(100 * sum(r["names_ms"] for r in whistle.values()) / 1000 / sum(r["audio_s"] for r in whistle.values()))}}
total_audio = sum(r["audio_s"] for r in whistle.values())
for name in ["tiny.en", "base.en", "small.en", "distil-small.en"]:
    model = WhisperModel(name, device="cpu", compute_type="int8", cpu_threads=2)
    hyp, spent = {}, 0.0
    for path in sorted(glob.glob(f"{folder}/u*.wav")):
        t = time.perf_counter()
        segs, _ = model.transcribe(path, language="en", beam_size=1, initial_prompt=prompt, vad_filter=False)
        hyp[os.path.basename(path)] = " ".join(s.text.strip() for s in segs); spent += time.perf_counter() - t
    d, k = score(hyp)
    out[name] = {"diff%": d, "key words kept%": k, "time vs audio%": round(100 * spent / total_audio)}
    json.dump(hyp, open(f"{folder}/hyp_{name}.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print(name, out[name], flush=True)
print(json.dumps(out, indent=1))
json.dump(out, open(f"{folder}/small_models.json", "w", encoding="utf-8"), indent=1)
import type { InvestigationEntities } from "@/lib/finance/investigation";
import { shiftDays } from "./voice-query";
import { spoken } from "./voice-query-editor";

/**
 * The draft of something the owner is adding by voice ("I spent five euros at Rewe, add that"). It has
 * the same fields as the chat tool's transaction card, so it becomes that card: nothing is saved
 * until the owner taps it. Speech edits the draft the way it edits a question card, and the last
 * thing said wins ("not Rewe, Lidl", "not ten, twenty").
 */
export type Draft = {
  direction: "spent" | "received";
  /** A positive decimal, exactly as said: "5", "1.5", "1343". */
  amount: string | null;
  currency: string;
  merchant: string | null; category: string | null; account: string | null;
  date: string;
};

const tokenize = (text: string) => text.normalize("NFKC").toLowerCase().replace(/['’]/g, "").match(/\d+(?:[.,]\d+)?|\p{L}+|[$€£]/gu) ?? [];
const UNITS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const CURRENCY: Record<string, string> = { euro: "EUR", euros: "EUR", eur: "EUR", "€": "EUR", dollar: "USD", dollars: "USD", bucks: "USD", "$": "USD", pound: "GBP", pounds: "GBP", quid: "GBP", "£": "GBP", franc: "CHF", francs: "CHF" };

/** A number at `at`, in digits ("1.5", "1,50") or words ("a hundred and twenty"). */
function readAmount(tokens: string[], at: number): { amount: string; length: number } | null {
  if (/^\d/.test(tokens[at] ?? "")) {
    const [whole, fraction = ""] = tokens[at].split(/[.,]/);
    // "1,343" is a thousands separator, "1,5" a decimal.
    if (fraction.length === 3) return { amount: String(Number(whole + fraction)), length: 1 };
    return fraction.length > 2 ? null : { amount: fraction ? `${Number(whole)}.${fraction}` : String(Number(whole)), length: 1 };
  }
  let total = 0, current = 0, length = 0;
  for (let i = at; i < tokens.length; i++) {
    const word = tokens[i], next = tokens[i + 1] ?? "", unit = UNITS.indexOf(word), ten = TENS.indexOf(word);
    if (unit >= 0) current += unit;
    else if (ten >= 2) current += ten * 10;
    else if (word === "hundred") current = (current || 1) * 100;
    else if (word === "thousand") { total += (current || 1) * 1000; current = 0; }
    else if (word === "a" && i === at && (next === "hundred" || next === "thousand")) continue;
    else if (word === "and" && length && (UNITS.includes(next) || TENS.indexOf(next) >= 2)) continue;
    else break;
    length = i - at + 1;
  }
  return length && total + current > 0 ? { amount: String(total + current), length } : null;
}

const ADD = /\b(add|log|record|note|put (it|that) (in|down))\b|\bi (just )?(spent|paid|bought|got|received|earned)\b|\bcost me\b|\bi have to (spend|pay)\b/;
// A question about the amount, or a what-if, is the chat model's: "is that above my median", "how much will I save".
const ASK = /\b(how much|how many|what|why|should|would|if|median|average|compare|tell me|check|is it|are they|per month|every month|monthly|subscription|i have \d+|i have (a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred)\b)\b/;
const RECEIVED = /\b(salary|paycheck|got paid|received|earned|refund|income|wage|wages)\b/;
const CORRECT = new Set(["no", "nope", "not", "sorry", "actually", "wait", "oops", "correction"]);
const NOT_MONEY = new Set(["day", "days", "week", "weeks", "month", "months", "year", "years", "percent", "times", "people", "items", "minutes", "hours", "km", "kilometers"]);

/**
 * The draft after this utterance. With `base`, an utterance that only corrects ("no, it's 24", "not
 * Rewe, Lidl") edits that draft; one that adds something new starts over.
 *
 * `ready` means code may show the card: the owner asked to add something, the amount is clear, and a
 * shop or category they already have names it. Anything else is left to the chat model.
 */
export function editDraft(base: Draft | null, utterance: string, entities: InvestigationEntities, today: string, currency: string): { draft: Draft; adds: boolean; corrects: boolean; ready: boolean; unclear: string[] } {
  const tokens = tokenize(utterance), text = tokens.join(" ");
  const adds = ADD.test(text) && !ASK.test(text);
  const corrects = !adds && base !== null && tokens.some(token => CORRECT.has(token)) && !ASK.test(text);
  const draft: Draft = corrects ? { ...base! } : { direction: RECEIVED.test(text) ? "received" : "spent", amount: null, currency, merchant: null, category: null, account: null, date: today };
  const unclear: string[] = [];

  const names = new Map<string, { kind: "merchant" | "category" | "account"; name: string }[]>();
  let longest = 1;
  for (const [kind, key] of [["merchant", "merchants"], ["category", "categories"], ["account", "accounts"]] as const) for (const entity of entities[key]) {
    const sound = spoken(tokenize(entity.name));
    longest = Math.max(longest, sound.split(" ").length + 2);
    names.set(sound, [...(names.get(sound) ?? []), { kind, name: entity.name }]);
  }

  // Every number said, in order: with a currency or not, and whether it came after "no" or "sorry".
  const said: { amount: string; money: boolean; corrected: boolean }[] = [];
  let negated = false, corrected = false;
  for (let at = 0; at < tokens.length;) {
    if (tokens[at] === "not") { negated = true; at++; continue; }
    if (tokens[at] === "yesterday") { draft.date = shiftDays(today, -1); at++; continue; }
    let matched = 0;
    for (let length = Math.min(longest, tokens.length - at); length > 0 && !matched; length--) {
      const found = names.get(spoken(tokens.slice(at, at + length)));
      if (!found) continue;
      matched = length;
      if (found.length > 1) unclear.push(tokens.slice(at, at + length).join(" "));
      // "Not Rewe" takes Rewe back; any other mention replaces what was said before.
      else if (negated) { if (draft[found[0].kind] === found[0].name) draft[found[0].kind] = null; }
      else draft[found[0].kind] = found[0].name;
    }
    if (matched) { at += matched; negated = false; continue; }
    const symbol = /^[$€£]$/.test(tokens[at]) ? CURRENCY[tokens[at]] : null;
    const number = readAmount(tokens, symbol ? at + 1 : at);
    if (number) {
      const end = (symbol ? at + 1 : at) + number.length, unit = CURRENCY[tokens[end] ?? ""], money = symbol ?? unit;
      if (NOT_MONEY.has(tokens[end] ?? "")) { at = end + 1; negated = false; continue; }
      // "20 to 25 euros" and "13 43" are not one amount.
      const second = tokens[end] === "to" ? readAmount(tokens, end + 1) : money ? null : readAmount(tokens, end);
      if (second) {
        unclear.push(tokens.slice(at, end + (tokens[end] === "to" ? 1 : 0) + second.length).join(" "));
        at = end + (tokens[end] === "to" ? 1 : 0) + second.length;
        if (CURRENCY[tokens[at] ?? ""]) at++;
        negated = false;
        continue;
      }
      // "Not ten euros, twenty": the negated number is the one being replaced.
      if (!negated) said.push({ amount: number.amount, money: Boolean(money), corrected });
      if (money) draft.currency = money;
      at = end + (unit ? 1 : 0);
      negated = false;
      continue;
    }
    if (CORRECT.has(tokens[at])) corrected = true;
    if (!CORRECT.has(tokens[at])) negated = negated && /^(it|its|even|the|was|is|at|on|for)$/.test(tokens[at]);
    at++;
  }
  // The amount is the last number with a currency, unless a bare number corrects it afterwards ("no, 24").
  // A bare number alone counts only when it is the single one said.
  const priced = said.findLastIndex(item => item.money), later = said.findLastIndex((item, index) => index > priced && item.corrected);
  const chosen = later >= 0 ? said[later] : priced >= 0 ? said[priced] : said.length === 1 ? said[0] : null;
  if (chosen) draft.amount = chosen.amount;
  // "Around 20 to 25 euros. Sorry, it's 28": the correction settles what the estimate left open.
  if (chosen?.corrected) unclear.splice(0, unclear.length, ...unclear.filter(item => !/^\d/.test(item)));
  if (draft.amount === null) unclear.push("amount");
  if (!draft.merchant && !draft.category) unclear.push("what for");
  return { draft, adds, corrects, ready: (adds || corrects) && unclear.length === 0, unclear };
}

/** The draft as the input of the chat tool's transaction card (`transaction_propose`). */
export function draftProposal(draft: Draft) {
  if (draft.amount === null) throw new Error("The draft has no amount");
  return {
    direction: draft.direction, amount: draft.amount, currency: draft.currency, date: draft.date,
    description: [draft.merchant, draft.merchant ? draft.category?.toLowerCase() : draft.category].filter(Boolean).join(" ") || "Voice entry",
    ...(draft.account ? { account: draft.account } : {}), ...(draft.category ? { category: draft.category } : {}),
  };
}

import type { InvestigationEntities } from "@/lib/finance/investigation";
import { emptyCard, periods, type Card, type Period, type Ref } from "./voice-query";

type Kind = "categories" | "merchants" | "accounts";
const KINDS: Kind[] = ["categories", "merchants", "accounts"];

export const words = (text: string) => text.normalize("NFKC").toLowerCase().replace(/['’]/g, "").replace(/[^\p{L}\p{N}]+/gu, " ").trim().split(" ").filter(Boolean);
// "Groceries" and "grocery" are the same name when spoken.
const stem = (word: string) => word.length > 3 && word.endsWith("ies") ? `${word.slice(0, -3)}y` : word.length > 3 && word.endsWith("s") && !word.endsWith("ss") ? word.slice(0, -1) : word;

const SMALL = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
function readNumber(tokens: string[], at: number): { value: number; length: number } | null {
  const token = tokens[at] ?? "";
  if (/^\d{1,3}$/.test(token)) return { value: Number(token), length: 1 };
  const small = SMALL.indexOf(token);
  if (small > 0) return { value: small, length: 1 };
  const tens = TENS.indexOf(token);
  if (tens < 2) return null;
  const ones = SMALL.indexOf(tokens[at + 1] ?? "");
  return ones > 0 && ones < 10 ? { value: tens * 10 + ones, length: 2 } : { value: tens * 10, length: 1 };
}
function readYear(tokens: string[], at: number): { value: number; length: number } | null {
  if (/^20\d\d$/.test(tokens[at] ?? "")) return { value: Number(tokens[at]), length: 1 };
  if (tokens[at] !== "twenty") return null;
  const rest = readNumber(tokens, at + 1);
  return rest && rest.value >= 10 ? { value: 2000 + rest.value, length: 1 + rest.length } : null;
}

/** How a name sounds: number words become digits and "N26" splits into "n 26", so "n twenty six" finds it. */
export function spoken(tokens: string[]) {
  const out: string[] = [];
  for (let at = 0; at < tokens.length;) {
    const number = /^\d+$/.test(tokens[at]) ? null : readNumber(tokens, at);
    if (number) out.push(String(number.value));
    else out.push(...(tokens[at].match(/\d+|\D+/g) ?? []));
    at += number?.length ?? 1;
  }
  return out.map(stem).join(" ");
}

const UNITS: Record<string, "day" | "week" | "month" | "year"> = { day: "day", days: "day", week: "week", weeks: "week", month: "month", months: "month", year: "year", years: "year" };
const MONTH_WORDS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"];
const MONTH_SHORT = ["jan", "feb", "mar", "apr", "", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const monthOf = (word = "") => (MONTH_WORDS.indexOf(word) + 1 || MONTH_SHORT.indexOf(word) + 1 || (word === "sept" ? 9 : 0)) as number;
const BEFORE_MAY = new Set(["in", "for", "during", "of", "since", "last", "this"]);

/** A period phrase starting at `at`: "last month", "the past thirty days", "October 2025", "the month before". */
function readPeriod(tokens: string[], at: number, today: string, current: Period): { period: Period; length: number } | null {
  const year = Number(today.slice(0, 4)), month = Number(today.slice(5, 7));
  const found = (period: Period, end: number) => ({ period, length: end - at });
  if (tokens[at] === "today") return found(periods.day(today, 0), at + 1);
  if (tokens[at] === "yesterday") return found(periods.day(today, -1), at + 1);
  if (tokens[at] === "ytd") return found(periods.year(today, 0), at + 1);
  const start = tokens[at] === "the" ? at + 1 : at;
  const word = tokens[start], unit = UNITS[word];
  // "This month", and "the whole year" said without "this".
  if (word === "this" || word === "current" || word === "whole" || word === "entire") {
    const next = UNITS[tokens[start + 1]];
    if (next && next !== "day") return found(periods[next](today, 0), start + 2);
    if (word === "this" && monthOf(tokens[start + 1])) return found(periods.named(today, monthOf(tokens[start + 1]), year), start + 2);
  }
  if (word === "last" || word === "previous" || word === "past" || word === "prior") {
    const count = readNumber(tokens, start + 1), counted = count && UNITS[tokens[start + 1 + count.length]];
    if (count && counted) return found(counted === "year" ? periods.rolling(today, count.value * 12, "month") : periods.rolling(today, count.value, counted), start + 2 + count.length);
    const next = UNITS[tokens[start + 1]];
    if (next && next !== "day") return found(word === "past" ? next === "year" ? periods.rolling(today, 12, "month") : periods.rolling(today, 1, next) : periods[next](today, -1), start + 2);
    const named = monthOf(tokens[start + 1]);
    // "Last October" is the latest October that has ended.
    if (named && word === "last") return found(periods.named(today, named, named < month ? year : year - 1), start + 2);
  }
  const span = readNumber(tokens, start);
  if (span && UNITS[tokens[start + span.length]] && tokens[start + span.length + 1] === "before") return found(periods.before(current, today), start + span.length + (tokens[start + span.length + 2] === "that" ? 3 : 2));
  if (unit && unit !== "day" && tokens[start + 1] === "before") {
    if (tokens[start + 2] === "last") return found(periods[unit](today, -2), start + 3);
    return found(periods.before(current, today), start + (tokens[start + 2] === "that" ? 3 : 2));
  }
  // "Make it sixty days": a bare length of time is the time up to today.
  if (span && UNITS[tokens[start + span.length]]) {
    const length = UNITS[tokens[start + span.length]];
    return found(length === "year" ? periods.rolling(today, span.value * 12, "month") : periods.rolling(today, span.value, length), start + span.length + 1);
  }
  if (unit && unit !== "day" && tokens[start + 1] === "to" && tokens[start + 2] === "date") return found(periods[unit](today, 0), start + 3);
  if (start !== at) return null;
  const named = monthOf(word);
  if (named) {
    const stated = readYear(tokens, at + 1);
    // "May" is also a verb: only a month after a preposition or before a year.
    if (word === "may" && !stated && !BEFORE_MAY.has(tokens[at - 1])) return null;
    return found(periods.named(today, named, stated?.value), at + 1 + (stated?.length ?? 0));
  }
  const stated = readYear(tokens, at);
  return stated ? found(periods.year(today, stated.value - year), at + stated.length) : null;
}

const phrases = <T>(table: Record<string, T>) => new Map(Object.entries(table).flatMap(([names, value]) => names.split("|").map(name => [name, value] as const)));
const counted = "transactions|purchases|payments|times";
const METRICS = phrases<Card["metric"]>({
  "spend|spent|spending|pay|paid|paying|cost|costs|expense|expenses|purchase|purchases|went|blow|blew|outgoings": "spending",
  "earn|earned|earning|earnings|income|make|made|receive|received|get|got|got paid|get paid|came in|come in|coming in": "income",
  "net|net income|save|saved|saving|left over|leftover|cash flow|cashflow": "net",
  [`how many|how often|number of|count|${counted.split("|").map(noun => `how many ${noun}|number of ${noun}`).join("|")}`]: "count",
});
const DIMENSIONS = phrases<NonNullable<Card["groupBy"]>>({
  "category|categories": "category", "merchant|merchants|shop|shops|store|stores|place|places": "merchant", "account|accounts": "account", "month|months": "month",
});
const BY = new Set(["by", "per", "each", "every", "which", "what", "top", "biggest", "largest", "main"]);
const GROUPS = phrases<NonNullable<Card["groupBy"]>>({
  "where did my money go|where did all my money go|where does my money go|where does all my money go|where did the money go|where did it all go|where is my money going|what did i spend the most on|breakdown|break down|broken down": "category", "where|where did i spend the most": "merchant", "monthly": "month",
});
const COMPARE = new Set(["compared to", "compared with", "compare to", "compare with", "compare", "comparing", "compared", "comparison", "versus", "vs", "against", "than"]);
const BARE = new Set(["compare", "comparing", "comparison"]);
const CORRECT = new Set(["no", "nope", "actually", "wait", "sorry", "rather", "instead", "oops", "correction", "i mean", "i meant", "scratch that", "make that", "make it", "hang on", "hold on"]);
const PAUSES = new Set("um uh er erm hmm ah oh okay ok so well hey moneo yeah yes right".split(" "));
const QUESTION = new Set(["how", "what", "whats", "can", "could", "would", "tell", "show", "check", "give", "find"]);
const LEADS = new Set(["and", "what about", "how about", "same for", "same", "also", "or", "but", "then", "now", "not"]);
const FILLERS = new Set([...PAUSES, ...`how much many did do does i ive have has had we my me mine our the a an on in at for of to from with and
  please hi hello like you know tell show give get let see whats what is was were are be been it its that this
  total all altogether overall money amount sum far until now up just only then about there any im id want wanna need wondering curious
  quickly quick question thanks thank during over within into back anything something end go buy bought order ordered take took trip trips come came said say both shop shopped wanted ask check find exactly more less also or but same`.split(/\s+/)]);

// "Can you tell me…" is politeness; "how much can I spend" asks something else.
const POLITE = new Set(["can you", "could you", "would you", "will you", "i would", "get me", "give me"]);

const COUNTED = new Set(["transactions", "purchases", "payments", "times", "orders", "rides", "trips", "visits", "charges"]);
const RANKING = new Set(["most", "break", "down", "rank", "ranked", "ranking", "split", "sort", "sorted", "top", "biggest", "largest", "highest"]);

type Match = { length: number; apply: () => void };

/**
 * Rewrites the card from everything said so far in the current utterance. It is re-run on every new
 * word, always from the card the utterance started with, so a correction ("last month, no, this
 * month") or a word that changes the meaning simply produces a different card.
 * Pass `base` as null at the start of a call and after any turn the chat model answered.
 *
 * `leftover` holds every word the rules could not account for. A card is only safe to answer when
 * it is empty: an unexplained word may change the question, and then the chat model takes over.
 */
export function editCard(base: Card | null, utterance: string, entities: InvestigationEntities, today: string): { card: Card; leftover: string[]; touched: boolean } {
  const tokens = words(utterance);
  const names = new Map<string, { kind: Kind; ref: Ref }[]>();
  let longest = 1;
  for (const kind of KINDS) for (const entity of entities[kind]) {
    const key = spoken(words(entity.name));
    if (!key) continue;
    // A spoken number can take two words ("twenty six").
    longest = Math.max(longest, key.split(" ").length + 2);
    names.set(key, [...(names.get(key) ?? []), { kind, ref: { id: entity.id, name: entity.name } }]);
  }
  const join = (at: number, length: number) => at + length <= tokens.length ? tokens.slice(at, at + length).join(" ") : "";
  const longestIn = (table: { has(key: string): boolean }, at: number, max: number) => {
    for (let length = max; length > 0; length--) if (table.has(join(at, length))) return length;
    return 0;
  };

  const first = tokens.findIndex(token => !PAUSES.has(token));
  const follows = first >= 0 && (LEADS.has(tokens[first]) || LEADS.has(join(first, 2)) || CORRECT.has(tokens[first]) || CORRECT.has(join(first, 2)));
  const asks = tokens.some((_, at) => longestIn(METRICS, at, 3) > 0);
  // A full question starts a new card; anything shorter ("and last month?", "no, groceries") edits the old one.
  // "Can you check how my groceries are this year" has no money verb but is a whole question, not a fragment.
  const framed = tokens.some(token => QUESTION.has(token));
  const start = base && (follows || (!asks && !framed)) ? base : emptyCard(today);
  const card: Card = { ...start, categories: [...start.categories], merchants: [...start.merchants], accounts: [...start.accounts] };
  const leftover: string[] = [];
  const replace = new Set<Kind>(KINDS), mentioned = new Set<Kind>();
  let touched = false, corrected = false, negate = false, slot: "period" | "comparison" = "period";
  let comparing: string | null = null, account = false, dated = false, grouped = false, revised = false, joined = false;

  const closeComparison = () => {
    if (!comparing) return;
    // "How does that compare?" means the period before; a bare "than" means something we did not catch.
    if (comparing.startsWith("compar")) card.comparison = periods.before(card.period, today);
    else leftover.push(comparing);
    comparing = null;
  };

  for (let at = 0; at < tokens.length;) {
    const options: Match[] = [], afterAccount = account;
    account = false;
    const period = readPeriod(tokens, at, today, card.period);
    if (period) options.push({ length: period.length, apply() {
      // "Compare rent this month to August": after a bare "compare", the first period is the main one.
      const main = comparing !== null && BARE.has(comparing) && !dated;
      // "This month and also last month" asks for two answers; one card holds one.
      if (dated && joined && !corrected && !comparing) leftover.push("and");
      joined = false;
      slot = main ? "period" : comparing ? "comparison" : corrected ? slot : "period";
      card[slot] = period.period;
      dated = true;
      if (!main) comparing = null;
    } });
    const metric = CORRECT.has(join(at, 2)) || POLITE.has(join(at, 2)) ? 0 : longestIn(METRICS, at, 3);
    if (metric) options.push({ length: metric, apply() {
      const value = METRICS.get(join(at, metric))!;
      // "How many times did I pay…" stays a count.
      if (card.metric !== "count" || value === "count" || start.metric === "count" || revised) card.metric = value;
    } });
    const dimension = BY.has(tokens[at]) ? DIMENSIONS.get(tokens[at + 1] ?? "") : undefined;
    const group = longestIn(GROUPS, at, 7);
    if (dimension) options.push({ length: 2, apply() { card.groupBy = dimension; grouped = true; } });
    else if (group) options.push({ length: group, apply() {
      // "Monthly breakdown": a plain "breakdown" never replaces the grouping just asked for.
      const general = join(at, group).startsWith("br");
      if (!general || !grouped) card.groupBy = GROUPS.get(join(at, group))!;
      grouped ||= !general;
    } });
    for (let length = Math.min(longest, tokens.length - at); length > 0; length--) {
      const matches = names.get(spoken(tokens.slice(at, at + length)));
      if (!matches) continue;
      options.push({ length, apply() {
        // The same name on two things is a question for the owner, never a guess.
        if (matches.length > 1) { leftover.push(join(at, length)); return; }
        const [{ kind, ref }] = matches, without = card[kind].filter(item => item.id !== ref.id);
        if (negate) {
          if (without.length === card[kind].length && !start[kind].some(item => item.id === ref.id)) leftover.push("not");
          card[kind] = without;
        } else {
          card[kind] = replace.has(kind) ? [ref] : [...without, ref];
          replace.delete(kind);
        }
        mentioned.add(kind);
        account = kind === "accounts";
      } });
      break;
    }
    const best = options.reduce<Match | null>((winner, option) => !winner || option.length > winner.length ? option : winner, null);
    if (best) {
      best.apply();
      touched = true; corrected = false; negate = false;
      at += best.length;
      continue;
    }
    const compare = longestIn(COMPARE, at, 2), correct = longestIn(CORRECT, at, 2);
    if (compare) {
      closeComparison();
      comparing = join(at, compare);
      touched = true;
      at += compare;
    } else if (correct) {
      closeComparison();
      corrected = true; revised = true; negate = false;
      for (const kind of KINDS) replace.add(kind);
      at += correct;
    } else if (POLITE.has(join(at, 2))) {
      at += 2;
    } else if (afterAccount && (tokens[at] === "card" || tokens[at] === "account")) {
      at++; // "my N26 card"
    } else {
      if (tokens[at] === "and" || tokens[at] === "also" || tokens[at] === "plus") joined = true;
      if (tokens[at] === "not") negate = true;
      else if (!FILLERS.has(tokens[at])) leftover.push(tokens[at]);
      at++;
    }
  }
  closeComparison();
  // "How much is in my Revolut" asks for something, but not for any amount this card can hold.
  if (start !== base && !asks && mentioned.has("accounts") && !mentioned.has("categories") && !mentioned.has("merchants")) leftover.push("how much");
  // "And last month?" needs a question to follow. After a turn the chat model answered there is none here.
  if (follows && !base) leftover.push(tokens[first]);
  // Income has no "groceries": a switch between spending and income drops filters nobody repeated.
  if (start === base && card.metric !== start.metric && card.metric !== "count" && start.metric !== "count") {
    if (!mentioned.has("categories")) card.categories = [];
    if (!mentioned.has("merchants")) card.merchants = [];
  }
  // "Which account did I spend the most from" only asks for the ranking a breakdown already gives.
  return { card, leftover: leftover.filter(word => !(card.groupBy && RANKING.has(word)) && !(card.metric === "count" && COUNTED.has(word))), touched };
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import type { InvestigationEntities } from "@/lib/finance/investigation";
import { loadInvestigationEntities, runInvestigation } from "@/lib/finance/investigation-reader";
import { draftProposal, editDraft, type Draft } from "./voice-draft";
import { toInvestigation, type Card } from "./voice-query";
import { editCard } from "./voice-query-editor";
import { answerSegments, speak } from "./voice-say";

const refs = z.array(z.object({ id: z.uuid(), name: z.string().min(1).max(120) }).strict()).max(20);
const period = z.object({ from: z.iso.date(), to: z.iso.date(), say: z.string().min(1).max(80) }).strict();
const cardSchema = z.object({
  metric: z.enum(["spending", "income", "net", "count"]), categories: refs, merchants: refs, accounts: refs,
  period, comparison: period.optional(), groupBy: z.enum(["category", "merchant", "account", "month"]).optional(),
}).strict();

const name = z.string().min(1).max(120).nullable();
const draftSchema = z.object({
  direction: z.enum(["spent", "received"]), amount: z.string().regex(/^\d{1,15}(\.\d{1,2})?$/).nullable(), currency: z.string().regex(/^[A-Z]{3}$/),
  merchant: name, category: name, account: name, date: z.iso.date(),
}).strict();
/** What a call remembers between turns: the last question card, or the last draft and the request that made its card. */
const stateSchema = z.object({ card: z.unknown().optional(), draft: draftSchema.optional(), draftRequestId: z.uuid().optional() }).strict();
export type VoiceState = { card?: Card; draft?: Draft; draftRequestId?: string };

type Context = { supabase: SupabaseClient; workspace: { id: string } };

/**
 * A call turn answered by code instead of the chat model: the words edit the question card, and the
 * same investigation the chat tool uses answers it. Null when a word was not understood or the
 * answer does not fit one sentence. It never writes.
 *
 * `previous` is the last card as the browser sent it back, so it is trusted only where every name
 * on it is still the owner's.
 */
export async function voiceFastPath(context: Context, message: string, previous: unknown, today: string, canReadImports: boolean, known?: InvestigationEntities): Promise<{ answer: string; card: Card; query: ReturnType<typeof toInvestigation> } | null> {
  const entities = known ?? await loadInvestigationEntities(context);
  const parsed = cardSchema.safeParse(previous);
  const owned = parsed.success && (["categories", "merchants", "accounts"] as const).every(kind =>
    parsed.data[kind].every(item => entities[kind].some(entity => entity.id === item.id && entity.name === item.name)));
  const { card, leftover, touched } = editCard(owned ? parsed.data : null, message, entities, today);
  if (!touched || leftover.length) return null;
  const query = toInvestigation(card);
  const result = await runInvestigation(query, context, { canReadImports, sourceVersions: false, entities: Promise.resolve(entities) });
  const segments = answerSegments(card, result, entities, "digits");
  return segments && { answer: speak(segments), card, query };
}

/**
 * One call turn for code, if code can take it: a question it can answer, or something to add that it
 * can draft. A draft is only described here; the caller makes the card, which the owner still has to
 * tap. `replaces` names the request whose card this draft corrects.
 */
export async function voiceFastTurn(context: Context, message: string, previous: unknown, today: string, currency: string, canReadImports: boolean): Promise<
  | { kind: "answer"; answer: string; card: Card; query: ReturnType<typeof toInvestigation> }
  | { kind: "draft"; draft: Draft; input: ReturnType<typeof draftProposal>; replaces: string | null }
  | null> {
  const entities = await loadInvestigationEntities(context);
  const state = stateSchema.safeParse(previous);
  const answered = await voiceFastPath(context, message, state.success ? state.data.card : null, today, canReadImports, entities);
  if (answered) return { kind: "answer", ...answered };
  const { draft, ready, corrects } = editDraft(state.success ? state.data.draft ?? null : null, message, entities, today, currency);
  return ready ? { kind: "draft", draft, input: draftProposal(draft), replaces: corrects && state.success ? state.data.draftRequestId ?? null : null } : null;
}
