import { expect, it } from "vitest";
import type { InvestigationEntities } from "@/lib/finance/investigation";
import { draftProposal, editDraft, type Draft } from "./voice-draft";

const today = "2026-11-16";
const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
const entities: InvestigationEntities = {
  categories: [{ id: id(1), name: "Groceries" }, { id: id(2), name: "Salary" }],
  merchants: [{ id: id(11), name: "Rewe" }, { id: id(12), name: "Lidl" }, { id: id(13), name: "Amazon" }],
  accounts: [{ id: id(21), name: "N26" }],
};
const say = (text: string, base: Draft | null = null) => editDraft(base, text, entities, today, "EUR");

// The sentences below are how the owner really said them in a recording.
it("fills a draft from an add request and lets the last correction win", () => {
  const shop = say("Can you add that I spent 5 euros on Rewe for groceries? Oh sorry it was not Rewe, it was Lidl.");
  expect(shop).toMatchObject({ ready: true, draft: { direction: "spent", amount: "5", currency: "EUR", merchant: "Lidl", category: "Groceries", date: today } });
  expect(draftProposal(shop.draft)).toEqual({ direction: "spent", amount: "5", currency: "EUR", date: today, description: "Lidl groceries", category: "Groceries" });
  expect(say("I spent a hundred and twenty euros on Amazon yesterday, can you add that?").draft).toMatchObject({ amount: "120", merchant: "Amazon", date: "2026-11-15" });
  expect(say("add 1,50 € at Rewe, sorry, not ten euros, it's twenty euros").draft.amount).toBe("20");
  expect(say("I just got paid my salary into N26, 1,343 euros, add that").draft).toMatchObject({ direction: "received", amount: "1343", category: "Salary", account: "N26" });
});

it("edits the last draft when the next turn only corrects it", () => {
  const first = say("I spent ten euros at Rewe, add that").draft;
  expect(say("No, it's not even 20, it's 24.", first)).toMatchObject({ ready: true, draft: { amount: "24", merchant: "Rewe" } });
  expect(say("sorry, at Lidl", first).draft).toMatchObject({ amount: "10", merchant: "Lidl" });
  // A new add starts a new draft instead of inheriting the old shop.
  expect(say("add 3 euros for groceries", first).draft).toMatchObject({ amount: "3", merchant: null, category: "Groceries" });
});

it("leaves anything it is not sure about to the chat model", () => {
  // No clear amount.
  expect(say("the ticket at Amazon is around 20 to 25 euros, add that")).toMatchObject({ ready: false, unclear: ["20 to 25", "amount"] });
  expect(say("the ticket at Amazon is around 20 to 25 euros. Sorry, it's 28 euros. Can you add that?")).toMatchObject({ ready: true, draft: { amount: "28" } });
  expect(say("I got my salary, it was 13 43, add that").ready).toBe(false);
  // Nothing the owner already has names it.
  expect(say("I spent 1.5 euros on cloth washing, can you add that")).toMatchObject({ ready: false, unclear: ["what for"], draft: { amount: "1.5" } });
  // Questions and what-ifs are not adds, even when they mention spending.
  expect(say("I went to Rewe and I spent 17 euros. Can you tell me, is it above the median?").adds).toBe(false);
  expect(say("how much did I spend at Rewe").adds).toBe(false);
  // A monthly cost is a recurring payment, and "I have 17 euros" is a balance: other cards.
  expect(say("I have this Amazon subscription which cost me 10 euros per month, add that").adds).toBe(false);
  expect(say("In my N26 right now I have 17 euros, add that").adds).toBe(false);
});
